class ReadInput:
    """One read call: where to resume and how long to wait."""

    stream: StreamRef

    after_token: str | None = None
    """A cursor from an earlier record, read or append of this stream. The read resumes
    strictly after the record it names. Absent or empty starts at the oldest record the
    stream retains. A cursor from another stream or another store is refused, and one
    whose record retention dropped is refused as expired.
    """

    max_records: int | None = None
    """Answer with at most this many stored records. 100 when absent. A supersession comes
    on top.
    """

    wait_ms: int | None = None
    """Wait at most this long for a record before answering. The handler shortens it to fit
    the request deadline. A call that collects nothing answers with no records and the
    caller's own cursor.
    """

    latest_only: bool | None = None
    """Answer with the cursor of the newest record and no records, for a reader that
    follows from now. Refused beside after_token.
    """

    state: bytes | None = None
    """The state of this read's previous answer, opaque to the caller. Absent on a read's
    first call. With it the endpoint knows which producer attempts the reader already
    saw, so its superseded and stale marks are exact across calls and across handler
    Workers. A state that doesn't parse is refused as a cursor mistake.
    """

    floor_holder: str | None = None
    """Names a reader that keeps the range of each answer in place of its records and reads
    the range again through read_range on replay. With it the endpoint holds the records
    after the read's start against retention for this holder, and the answer carries
    replay. Each read and read_range of the holder renews the hold, which lapses the
    store's floor lease after the last one. At most 512 bytes. Refused beside
    latest_only, which answers no records.
    """

    wake_token: str | None = None
    """The operation token of the reader's stream operation. When the call answers no
    records and not done, the endpoint asks the stream's notifier to wake that
    operation's callback once the stream moves past the answer, then reads once more, so
    a record that landed meanwhile is in the answer. A reader that finds records on each
    call never waits, and its operation hears nothing. Refused when the token names
    another stream.
    """


